import base64
import html
import json
from .pose import COLORS

def build_report(data,out):
    esc=lambda x:html.escape(str(x))
    sequence=data.get('actionSequence')
    sequence_html=''
    if sequence:
        states={'OBSERVED_SEQUENCE':'已观察完整顺序','INCOMPLETE':'未完整观察','EVIDENCE_GAP':'证据中断','REVIEW_SEQUENCE':'顺序需复核','OBSERVING':'观察中'}
        rows=''.join(f'<tr><td>{x["trackId"]}</td><td>{x["cycle"]}</td><td>{len(x["completed"])}/{len(sequence["workflow"]["config"]["steps"])}</td><td>{esc(states.get(x["status"],x["status"]))}</td></tr>' for x in sequence['subjects'])
        notes=''.join(f'<p>人物 {e["trackId"]} · {e["time"]}s：{esc(e["detail"])}</p>' for e in sequence['events'])
        sequence_html=f'<section><h2>动作顺序观察：{esc(sequence["workflow"]["config"]["name"])}</h2><p>{esc(sequence["scope"])}</p><table><tr><th>人物轨迹</th><th>轮次</th><th>观察步骤</th><th>状态</th></tr>{rows}</table>{notes}</section>'
    s=data['summary'];duration=data['source']['duration']; stats=data['actionSummary']
    bars=''.join(f'<div class="bar-row"><span>{esc(x["label"])}</span><div class="bar-track"><i style="width:{x["seconds"]/max(.01,s["personSeconds"])*100:.2f}%;background:{COLORS[x["action"]]}"></i></div><b>{x["seconds"]:.1f}s</b></div>' for x in stats)
    tracks=''.join(f'<tr><td>P{x["id"]:02}</td><td>{x["firstSeen"]:.2f}s</td><td>{x["lastSeen"]:.2f}s</td><td>{x["visibleSeconds"]:.2f}s</td><td>{x["meanConfidence"]*100:.1f}%</td><td>{x["segments"]}</td></tr>' for x in data['tracks'])
    segments=''.join(f'<tr><td>{i+1:02}</td><td>P{x["trackId"]:02}</td><td>{x["start"]:.2f}–{x["end"]:.2f}s</td><td>{x["duration"]:.2f}s</td><td><span style="color:{COLORS[x["action"]]}">{esc(x["label"])}</span></td><td>{x["meanConfidence"]*100:.1f}%</td><td>{esc(x["evidence"])}</td></tr>' for i,x in enumerate(data['segments']))
    events=''.join(f'<tr><td>{esc(x["title"])}</td><td>{x["start"]:.2f}–{x["end"]:.2f}s</td><td>{esc(x["description"])}</td><td>需人工复核</td></tr>' for x in data['events']) or '<tr><td colspan="4">未触发已配置的质量复核事件；不代表作业合规。</td></tr>'
    photos=''.join(f'<figure><img src="data:image/jpeg;base64,{base64.b64encode((out/x["image"]).read_bytes()).decode()}"><figcaption>{x["time"]:.2f}s · {esc(x["caption"])}</figcaption></figure>' for x in data['evidence'])
    limits=''.join(f'<li>{esc(x)}</li>' for x in data['limitations'])
    sop=''.join(f'<tr><td>{esc(x["name"])}</td><td>证据不足 · 待复核</td><td>{esc(x["reason"])}</td></tr>' for x in data['sop'])
    payload=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
    document=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>车间工人行为分析详细报告</title><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#edf2f8;color:#1c3049;font:14px/1.8 "Microsoft YaHei",system-ui,sans-serif}}main{{max-width:1120px;margin:30px auto;background:white;border-radius:14px;overflow:hidden;box-shadow:0 10px 50px #1232}}header{{padding:36px 44px;background:#112c50;color:white}}h1{{margin:8px 0;font-size:29px}}h2{{font-size:20px;margin:0 0 18px}}h3{{font-size:16px}}p{{margin:8px 0}}.eyebrow{{font-size:11px;letter-spacing:3px;color:#78c8fa}}.sub{{color:#b8cde4}}section{{padding:28px 44px;border-bottom:1px solid #e1e8ef}}.metrics{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}}.metric{{padding:17px;background:#f2f6fb;border-radius:8px}}.metric span{{font-size:12px;color:#627893;display:block}}.metric strong{{font-size:25px;color:#245d9d}}.note{{padding:15px 18px;border-left:4px solid #dda72b;background:#fff8e5;margin-top:18px}}table{{width:100%;border-collapse:collapse;font-size:12px}}th,td{{padding:10px 8px;border-bottom:1px solid #e2e8f0;text-align:left;vertical-align:top}}th{{background:#eff4fa;color:#526d8c}}.scroll{{overflow:auto}}.bar-row{{display:flex;align-items:center;gap:14px;margin:12px 0}}.bar-row>span{{width:170px}}.bar-track{{height:14px;background:#edf2f7;flex:1;border-radius:4px;overflow:hidden}}.bar-track i{{display:block;height:100%}}.bar-row>b{{width:60px;text-align:right}}.photos{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}figure{{margin:0}}figure img{{width:100%;border-radius:8px;background:#07132a}}figcaption{{font-size:12px;color:#617590}}.toolbar{{display:flex;gap:9px;margin-top:18px}}button{{border:0;border-radius:6px;padding:10px 17px;background:#246cbc;color:white;cursor:pointer}}.meta{{font-size:12px;color:#627893;overflow-wrap:anywhere}}ul{{padding-left:22px}}footer{{padding:25px 44px;color:#687f99;font-size:12px}}@media(max-width:700px){{main{{margin:0;border-radius:0}}header,section{{padding:24px 20px}}.metrics,.photos{{grid-template-columns:1fr 1fr}}.metric strong{{font-size:21px}}.bar-row>span{{width:120px;font-size:11px}}}}@media print{{body{{background:white}}main{{margin:0;box-shadow:none;max-width:none}}.toolbar{{display:none}}section{{break-inside:avoid;padding:20px 25px}}header{{padding:25px}}table{{font-size:10px}}.photos img{{max-height:210px;object-fit:contain}}}}
    </style></head><body><main><header><div class="eyebrow">AI-SOP / WORKER ANALYSIS REPORT</div><h1>车间工人行为分析详细报告</h1><p class="sub">{esc(data['source'].get('title','车间工人片段'))} · 实际模型离线分析 · 与视频时间同步回放</p><p class="sub">生成时间 {esc(data['generatedAt'])} · 报告编号 {esc(data['id'])}</p><div class="toolbar"><button onclick="window.print()">打印 / 保存为 PDF</button><button onclick="downloadJSON()">下载完整 JSON 数据</button></div></header>
    <section><h2>01 / 分析结论</h2><div class="metrics"><div class="metric"><span>分析时长</span><strong>{duration:.1f}s</strong></div><div class="metric"><span>采样分析帧</span><strong>{s['analyzedFrames']}</strong></div><div class="metric"><span>人员轨迹段（非身份）</span><strong>{s['trackCount']}</strong></div><div class="metric"><span>动作片段</span><strong>{s['segmentCount']}</strong></div></div><p>在 {duration:.1f} 秒的车间工人片段中，共有 {s['framesWithPeople']} 帧检测到人员，采样帧人员检出率 {s['presenceRate']*100:.1f}%，同时在场最多 {s['maxPeople']} 人。人员检测平均置信度为 {s['meanConfidence']*100:.1f}%。</p><p>姿态规则覆盖站立/原地作业、位置移动、抬手、手臂伸出、躯干前倾与姿态不确定。规则可判定人员观测占比 {s['actionCoverage']*100:.1f}%，其余观测保留为不确定。</p><div class="note"><b>工序合规结论：暂不可判定。</b>通用人体姿态模型没有验证工具、工件和装配质量。人员检测置信度不是动作准确率，不能把“抬手”直接当作“取到工具”或“装配完成”。</div></section>
    <section><h2>02 / 数据来源与分析方法</h2><p>{esc(data['source']['description'])}</p><p>源文件区间：{data['source']['start']:.2f}–{data['source']['end']:.2f}s；裁切区域：{esc(data['source']['crop'])}；有效画面 {data['source']['width']}×{data['source']['height']}。下方事件时间均相对裁切后片段起点。</p><p>模型：{esc(data['model']['name'])}；设备：{esc(data['model']['device'])}；每秒采样 {data['model']['sampleFps']} 帧；人体阈值 0.35；关键点阈值 0.35。轨迹以 IoU 与中心距离关联，最长跨 0.8 秒；不是人员身份识别。</p><p>动作使用关键点几何规则与最多 3 次采样的因果多数滤波。抬手：腕高于肩 0.10 倍躯干；伸臂：腕横向距肩大于 0.50 倍躯干且高于髋；前倾：肩髋倾角大于 32°；移动：0.55–1.2 秒窗口内髋部横移大于 0.12 身高/秒。单目投影与遮挡可能误判。</p>{f'<p>素材页面：<a href="{esc(data["source"]["url"])}">{esc(data["source"]["title"])}</a>；授权说明：{esc(data["source"]["license"])}</p>' if data['source'].get('url') else ''}<p class="meta">权重 SHA-256：{data['model']['sha256']}<br>源文件 SHA-256：{data['source']['sha256']}</p></section>
    <section><h2>03 / 人员检测明细</h2><div class="scroll"><table><thead><tr><th>轨迹编号</th><th>首次出现</th><th>末次采样</th><th>可见人员秒</th><th>平均检测置信度</th><th>动作片段数</th></tr></thead><tbody>{tracks}</tbody></table></div><p class="meta">可见人员秒按每个采样覆盖的实际区间累加；多人同时在场时可能超过视频时长。轨迹丢失后可能产生新编号，轨迹数不等于独立工人数。</p></section>
    <section><h2>04 / 动作时间分布</h2>{bars}<p class="meta">占比以所有检出人员的可见人员秒为分母，包含“不确定”。不是动作识别准确率。</p></section>
    <section><h2>05 / 完整动作时间轴</h2><div class="scroll"><table><thead><tr><th>序号</th><th>人员</th><th>起止时间</th><th>持续</th><th>动作规则标签</th><th>人体置信</th><th>判定依据</th></tr></thead><tbody>{segments}</tbody></table></div></section>
    <section><h2>06 / 关键帧证据</h2><p class="meta">青色框、青色骨架和 P 编号是本次模型输出。{'源视频还带有旧标注，旧标注不属于本次分析。' if data['source'].get('hasBurnedAnnotations') else '源视频旧标注未经核验，仅本次青色框和记录属于本次输出。'}</p><div class="photos">{photos}</div></section>
    <section><h2>07 / 质量事件与人工复核</h2><div class="scroll"><table><thead><tr><th>事件</th><th>时间范围</th><th>依据</th><th>处置建议</th></tr></thead><tbody>{events}</tbody></table></div><p class="meta">这些事件提示识别质量或证据缺口，不自动判定工人违规。</p></section>
    <section><h2>08 / SOP 步骤证据</h2><table><thead><tr><th>预期步骤</th><th>判定</th><th>缺失证据</th></tr></thead><tbody>{sop}</tbody></table><p>建议补充清晰的原始工位视频、工具/工件专用标签、区域边界和标准工序定义，再标注一批真实合格与违规样本进行验证。</p></section>
    <section><h2>09 / 性能与可复现参数</h2><p>单次模型推理均值 {s['meanInferenceMs']:.1f} ms，P95 {s['p95InferenceMs']:.1f} ms；分析及证据处理耗时（不含最终报告与清单写出） {s['processingSeconds']:.1f}s。统计来自本次离线运行，不是播放时的实时性能。</p><p>输入尺寸 {data['model'].get('inputSize',640)}；模型 {esc(data['model']['name'])}；设备 {esc(data['model']['device'])}；PyTorch {esc(data['model']['torchVersion'])}；采样进程工作集最大值 {s['peakMemoryMB']:.1f} MB；显存峰值 {s.get('peakGpuMemoryMB') or '—'} MB。</p><h3>数据解释与适用范围</h3><ul>{limits}</ul></section>{sequence_html}<footer>本报告基于实际模型输出和明确的姿态规则生成，未经人工真值验证。适用于原型测试和复核，不可直接作为生产验收或人员考核依据。</footer></main><script id="report-data" type="application/json">{payload}</script><script>function downloadJSON(){{const b=new Blob([document.getElementById('report-data').textContent],{{type:'application/json;charset=utf-8'}});const u=URL.createObjectURL(b);const a=document.createElement('a');a.href=u;a.download='工人行为分析完整数据.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}}</script></body></html>'''
    (out/'report.html').write_text(document,encoding='utf-8')
